html[data-theme] .atlas-modal-body .atlas-badge { margin: 0; padding: 2px 9px; border-radius: 999px; font-size: 11px; font-weight: 600; }
html[data-theme] .atlas-modal-body .atlas-notice { margin: 0; padding: 12px 14px; border-radius: 10px; font-size: 12.5px; line-height: 1.55; }
html[data-theme] .atlas-modal-body dl { grid-template-columns: 140px minmax(0, 1fr); gap: 0; overflow: hidden; border: 1px solid var(--line-soft); border-radius: 10px; font-size: 13px; }
html[data-theme] .atlas-modal-body :is(dt, dd) { padding: 10px 12px; border-top: 1px solid var(--line-soft); }
html[data-theme] .atlas-modal-body :is(dt, dd):is(:first-of-type) { border-top: 0; }
html[data-theme] .atlas-modal-body dt { background: var(--surface-raised); color: var(--muted); font-size: 11.5px; font-weight: 600; }
html[data-theme] .atlas-modal-body dd { color: var(--text); }
html[data-theme] .atlas-modal-body .atlas-form-error:empty { display: none; }
html[data-theme] .atlas-modal-body .atlas-form-error { padding: 10px 12px; border-radius: 9px; background: color-mix(in srgb, var(--coral) 14%, transparent); color: var(--coral); font-weight: 600; }
html[data-theme] .atlas-modal-body .atlas-service { --kind: var(--line); display: grid; gap: 8px; margin: 0; padding: 14px 16px; border: 1px solid var(--line-soft); border-radius: 10px; background: var(--surface-soft); box-shadow: none; }
html[data-theme] .atlas-modal-body .atlas-service > * { margin: 0; }
html[data-theme] .atlas-service[data-kind="note"] { --kind: var(--kind-note); }
html[data-theme] .atlas-service[data-kind="source"] { --kind: var(--kind-source); }
html[data-theme] .atlas-service[data-kind="task"] { --kind: var(--kind-task); }
html[data-theme] .atlas-service[data-kind="proposal"] { --kind: var(--kind-proposal); }
html[data-theme] .atlas-service[data-kind="decision"] { --kind: var(--kind-decision); }
html[data-theme] .atlas-service[data-kind="action"] { --kind: var(--kind-action); }
html[data-theme] .atlas-trace-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
html[data-theme] .atlas-modal-body .atlas-service .eyebrow { margin: 0; color: var(--kind); font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
html[data-theme] .atlas-modal-body .atlas-service[data-kind="note"] .eyebrow { color: var(--muted); }
html[data-theme] .atlas-clamp { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
html[data-theme] .atlas-trace-pins { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
html[data-theme] .atlas-trace-pins > span { margin-right: 2px; color: var(--faint); font-size: 11.5px; font-weight: 600; }
html[data-theme] .atlas-trace-links { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; }
html[data-theme] .atlas-trace-links li { display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 12.5px; }
html[data-theme] .atlas-trace-links b { color: var(--text); font-weight: 600; }
html[data-theme] .atlas-trace-links .board-icon-svg { flex: none; width: 13px; height: 13px; color: var(--faint); }
html[data-theme] .atlas-trace-item .atlas-buttons { margin-top: 2px; }
html[data-theme] .atlas-modal-body .atlas-timeline { margin: 0; }
html[data-theme] .atlas-modal-body .atlas-timeline-item { padding-bottom: 12px; }
@media (max-width: 560px) {
  html[data-theme] .modal-backdrop:has(.atlas-modal) { padding: 12px; }
  html[data-theme] .atlas-modal { max-height: calc(100dvh - 24px); border-radius: 12px; }
  html[data-theme] .atlas-modal-body { padding: 16px; }
  html[data-theme] .atlas-modal .modal-head { padding: 14px 12px 12px 16px; }
  html[data-theme] .atlas-modal .modal-actions { padding: 12px 16px; }
  html[data-theme] .atlas-modal-body dl { grid-template-columns: 1fr; }
  html[data-theme] .atlas-modal-body dt { border-top: 1px solid var(--line-soft); padding-bottom: 4px; }
  html[data-theme] .atlas-modal-body dd { border-top: 0; padding-top: 4px; }
}

/* Navigation and template previews: neutral controls with a brand accent; previews follow the theme like board thumbnails. */
html[data-theme] .side-link[aria-current="page"] { background: var(--surface-raised); color: var(--text); font-weight: 600; box-shadow: inset 3px 0 0 var(--brand); }
html[data-theme] .side-link[aria-current="page"] svg { color: var(--text); }
html[data-theme] .category-chip { border-color: var(--line-soft); background: transparent; color: var(--muted); }
html[data-theme] .category-chip:hover { border-color: var(--line); background: transparent; color: var(--text); }
html[data-theme] .category-chip[aria-pressed="true"] { border-color: var(--brand); background: transparent; color: var(--text); font-weight: 600; box-shadow: inset 0 0 0 1px var(--brand); }
html[data-theme] .template-art, html[data-theme] .template-art:is(.warm, .cool) { background-color: var(--bg); background-image: radial-gradient(var(--line-soft) .8px, transparent .8px); background-size: 12px 12px; border-bottom: 1px solid var(--line-soft); }
html[data-theme] .template-art-title { color: var(--text); font-weight: 600; }
html[data-theme] .template-link { background: var(--line-strong); opacity: 1; }
html[data-theme="light"] .template-block { --block-fill: #aed8ff; --block-border: #245fa7; }
html[data-theme="light"] .template-block.green { --block-fill: #8eebbc; --block-border: #23754d; }
html[data-theme="light"] .template-block.yellow { --block-fill: #ffe066; --block-border: #846000; }
html[data-theme="light"] .template-block.coral { --block-fill: #ffce91; --block-border: #985000; }
html[data-theme="dark"] .template-block { --block-fill: #204d78; --block-border: #8fcaff; --block-ink: #e4f3ff; }
html[data-theme="dark"] .template-block.green { --block-fill: #18563d; --block-border: #70dba8; --block-ink: #ddffee; }
html[data-theme="dark"] .template-block.yellow { --block-fill: #705015; --block-border: #f5cd47; --block-ink: #fff5d1; }
html[data-theme="dark"] .template-block.coral { --block-fill: #694015; --block-border: #ffbd61; --block-ink: #fff0dc; }
html[data-theme] .template-block { border-color: var(--block-border); background: var(--block-fill); color: var(--block-ink, #10243a); border-radius: 5px; box-shadow: 0 1px 2px #1b2b3f1f; }
html[data-theme="light"] .template-block { border-color: color-mix(in srgb, var(--block-border) 42%, var(--block-fill)); }
html[data-theme="light"] .template-art, html[data-theme="light"] .template-art:is(.warm, .cool) { background-color: #fff; background-image: radial-gradient(#d3dbe5 .9px, transparent .9px); }
html[data-theme] .template-link { z-index: 0; }
html[data-theme] .template-block { z-index: 1; }
html[data-theme] .side-link:hover { background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text); }
html[data-theme] .side-link[aria-current="page"], html[data-theme] .side-link[aria-current="page"]:hover { background: color-mix(in srgb, var(--text) 10%, transparent); color: var(--text); box-shadow: none; }
html[data-theme] .atlas-modal-body .atlas-service .eyebrow { display: inline-flex; align-items: center; gap: 7px; color: var(--muted); }
html[data-theme] .atlas-modal-body .atlas-service .eyebrow::before { content: ""; flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--kind); box-shadow: 0 0 0 3px color-mix(in srgb, var(--kind) 22%, transparent); }

/* Single product green: one accent per secondary CTA, neutral information chips. */
html[data-theme="light"] :is(.primary-button, .segment[aria-pressed="true"], .flow-tool-rail .icon-button[aria-pressed="true"]), html[data-theme="light"] :is(.atlas-panel-content, .atlas-modal) :is(.primary-button, .primary-button:hover) { border-color: var(--brand); }
html[data-theme] .starter-strip { border-color: var(--line-soft); background: var(--surface); }
html[data-theme] .starter-strip .outline-button { border-color: var(--brand); background: transparent; color: var(--text); }
html[data-theme] .starter-strip .outline-button:hover { border-color: var(--brand); background: transparent; color: var(--text); box-shadow: inset 0 0 0 1px var(--brand); }
html[data-theme] .access-chip, html[data-theme] .access-chip:not(.guest) { border-color: var(--line); background: transparent; color: var(--muted); }
html[data-theme] :is(.workspace-card, .board-card, .template-card):hover { border-color: var(--line-strong, var(--line)); }
html[data-theme="light"] :is(.primary-button, .segment[aria-pressed="true"]):hover { border-color: var(--brand); }

/* Modals use only the product green (#71efb2): no derived greens for text, hover fills or hover borders. */
html[data-theme] .atlas-modal, html[data-theme] .modal-backdrop:has(.atlas-modal) { --brand-text: var(--brand); --brand-soft: transparent; --brand-hover: var(--brand); --kind-decision: var(--brand); }
html[data-theme] .atlas-modal-heading .eyebrow { color: var(--muted); }
html[data-theme] .atlas-modal :focus-visible { outline-color: var(--text); }
html[data-theme] .atlas-modal :is(.quiet-button, .outline-button, .atlas-chip, .atlas-checkbox):hover:not(:disabled) { border-color: var(--brand); background: transparent; color: var(--text); }
html[data-theme] .atlas-modal .primary-button.primary-button.primary-button:not(:disabled), html[data-theme] .atlas-modal .primary-button.primary-button.primary-button:hover:not(:disabled) { border-color: var(--brand); background: var(--brand); box-shadow: none; }
html[data-theme] .atlas-modal .primary-button.primary-button.primary-button:hover:not(:disabled) { box-shadow: 0 0 0 3px color-mix(in srgb, var(--brand) 35%, transparent); }

/* Board navigation drawer: sits between the top bar and the status footer, with a single soft shadow to the right. */
html[data-theme] .board-app > .sidebar { bottom: 30px; border-right: 1px solid var(--line); box-shadow: 10px 0 24px -12px color-mix(in srgb, #000 30%, transparent); clip-path: inset(0 -40px 0 0); }
html[data-theme="light"] .board-app > .sidebar { box-shadow: 10px 0 24px -14px #1b2b3f40; }
